.modal-head h2 {
  margin: 9px 0 5px;
  font-family: var(--font-display);
  font-size: clamp(23px, 3vw, 33px);
  line-height: 1.05;
  color: #2f2417;
  letter-spacing: 0.01em;
}
.modal-sub {
  font-family: var(--font-pixel);
  font-size: 5.5px;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: #8b6d45;
}
.modal-body {
  display: grid;
  grid-template-columns: minmax(120px, 168px) 1fr;
  gap: clamp(16px, 3vw, 28px);
  align-items: start;
}
.modal-icon {
  width: 100%;
  aspect-ratio: 1;
  display: grid;
  place-items: center;
  color: #43331f;
  background:
    radial-gradient(circle at 40% 30%, #fdf8ed, #e1d2b3 75%);
  border: 1px solid #b8a078;
  box-shadow: inset 0 0 0 4px rgba(255, 255, 255, 0.35), 0 4px 12px rgba(82, 58, 30, 0.16);
}
.modal-icon svg { width: 72%; height: 72%; image-rendering: pixelated; filter: drop-shadow(1px 2px 0 rgba(72, 52, 28, 0.18)); }
.modal-copy { position: relative; }
.modal-copy p {
  margin: 0;
  font-size: clamp(14px, 1.6vw, 16px);
  line-height: 1.48;
  color: #3c2f20;
}
.modal-stamp {
  display: inline-block;
  margin-top: 20px;
  padding: 7px 12px;
  font-family: var(--font-pixel);
  font-size: 5px;
  line-height: 1.7;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  text-align: center;
  color: #8c3128;
  border: 2px solid #8c3128;
  opacity: 0.72;
  transform: rotate(-3deg);
}
