/* ------------------------------------------------------------
   ANIMATIONS
   ------------------------------------------------------------ */

@keyframes livePulse {
  0%, 100% { opacity: 1; box-shadow: 0 0 0 2px rgba(182, 75, 63, 0.2), 0 0 7px rgba(182, 75, 63, 0.8); }
  50% { opacity: 0.55; box-shadow: 0 0 0 4px rgba(182, 75, 63, 0.08), 0 0 4px rgba(182, 75, 63, 0.5); }
}
@keyframes stampIn {
  0% { opacity: 0; transform: translate(-50%, -50%) rotate(-14deg) scale(1.9); }
  65% { opacity: 1; transform: translate(-50%, -50%) rotate(-6deg) scale(0.97); }
  100% { opacity: 1; transform: translate(-50%, -50%) rotate(-7deg) scale(1); }
}
@keyframes valueBump {
  0% { transform: scale(1); }
  35% { transform: scale(1.28); }
  100% { transform: scale(1); }
}
@keyframes nudge {
  0%, 100% { transform: translateX(0); }
  25% { transform: translateX(-4px); }
  55% { transform: translateX(4px); }
  80% { transform: translateX(-2px); }
}
@keyframes resultIn {
  from { opacity: 0; transform: translateY(14px); }
  to { opacity: 1; transform: translateY(0); }
}
@keyframes sheetIn {
  from { opacity: 0; transform: translateY(12px) scale(0.985); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}

/* ------------------------------------------------------------
   RESPONSIVE
   ------------------------------------------------------------ */

@media (min-width: 1080px) and (min-height: 760px) {
  .app {
    height: 100dvh;
    overflow: hidden;
  }
  .main { flex: 1; min-height: 0; }
  .scene-column { min-height: 0; }
  .scene-frame {
    max-height: calc(100% - 112px);
    width: auto;
    max-width: 100%;
    height: auto;
    aspect-ratio: 16 / 9;
    align-self: center;
  }
  .docket-panel { height: 100%; }
  .docket-scroll { flex: 1; overflow-y: auto; }
  .page-foot { display: none; }
}

@media (max-width: 1240px) {
  .brand-text p { display: none; }
  .meter { width: clamp(104px, 11vw, 142px); }
  .key-legend { display: none; }
}

@media (max-width: 980px) {
  .app { padding: 10px 10px 20px; gap: 10px; }
  .hud {
    flex-wrap: wrap;
    gap: 10px;
    padding: 9px 12px;
  }
  .hud-cluster {
    flex: 1;
    gap: 10px;
    justify-content: flex-end;
  }
  .meters { flex: 1; max-width: none; }
