  .meters { gap: 10px; }
  .meter-label { font-size: 4.5px; }
  .meter-value { font-size: 13px; }
  .case-count { padding-left: 9px; }
  .case-count strong { font-size: 15px; }
  .sound-btn { width: 34px; height: 34px; flex-basis: 34px; }
  .scene-tag { top: 9px; left: 9px; font-size: 4.5px; padding: 5px 7px; gap: 5px; }
  .scene-caption-bar { font-size: 4.5px; padding: 14px 10px 7px; }
  .scene-caption-bar > span:last-child { display: none; }
  .docket-track { gap: 8px; padding: 7px 8px; margin-top: 7px; overflow: hidden; }
  .track-label, .track-progress { display: none; }
  .track-item { height: 20px; font-size: 4.5px; }
  .docket-scroll { padding: 11px 10px 10px; gap: 8px; }
  .docket-heading h2 { font-size: 23px; }
  .evidence-grid { grid-template-columns: 1fr; gap: 8px; }
  .evidence-detail { font-size: 12px; }
  .guideline-list { grid-template-columns: 1fr; }
  .action-dock { padding: 9px 10px 11px; }
  .sentence-row { align-items: flex-start; gap: 8px; }
  .action-label { padding-top: 3px; }
  .sentence-btn { flex-direction: column; align-items: flex-start; gap: 2px; padding: 6px 7px; font-size: 5px; }
  .sentence-btn small { font-size: 8px; }
  .verdict-btn { padding: 9px 9px 8px; }
  .verdict-btn span { font-size: 17px; letter-spacing: 0.05em; }
  .verdict-btn small { font-size: 9px; }
  .confirm-row { gap: 8px; }
  .verdict-hint { font-size: 11px; min-height: 26px; }
  .confirm-btn { padding: 9px 11px; font-size: 5.5px; gap: 6px; }
  .confirm-btn small { display: none; }
  .result-panel { padding: 11px 12px 12px; }
  .result-panel h3 { font-size: 18px; }
  .modal-body { grid-template-columns: 1fr; }
  .modal-icon { width: 130px; height: 130px; }
  .intro-steps { grid-template-columns: 1fr; margin: 18px auto 16px; }
  .intro-steps > div { display: grid; grid-template-columns: 30px auto; grid-template-rows: auto auto; column-gap: 8px; align-items: center; padding: 9px 11px; }
  .intro-steps span { grid-row: 1 / 3; margin: 0; font-size: 7px; }
  .intro-steps strong { margin: 0; font-size: 13px; }
  .intro-steps p { grid-column: 2; font-size: 11px; }
  .intro-lede { font-size: 14.5px; }
  .intro h1 { letter-spacing: 0.09em; }
  .intro-seal { width: 66px; height: 66px; margin-bottom: 10px; }
  .intro-foot { display: none; }
  .final-stats { grid-template-columns: 1fr; }
  .scene-stamp { padding: 9px 15px 8px; border-width: 2px; }
  .scene-stamp small { font-size: 4.5px; margin-bottom: 5px; }
  .scene-stamp span { font-size: 4.5px; margin-top: 5px; padding-top: 4px; }
}

@media (max-width: 400px) {
  .verdict-btn span { font-size: 15px; }
  .verdict-btn small { display: none; }
  .verdict-row { gap: 5px; }
  .case-stamp { display: none; }
  .track-item { font-size: 4px; }
}

/* accessibility */

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
    scroll-behavior: auto !important;
  }
}

