import { readFileSync, writeFileSync } from 'node:fs';
import { pathToFileURL } from 'node:url';

const src = '/home/runner/work/PlayGround/PlayGround/src/cases.js';
const { CASES } = await import(pathToFileURL(src).href);

const meta = {
  fine: {
    label: 'Para Cezası',
    short: 'Para',
    detail: 'Hafif, şiddet içermeyen suçlar. 500 doların altında kalan malvarlığı. İlk suç.',
  },
  year1: {
    label: '1 Yıl',
    short: '1 Yıl',
    detail: 'Önemli değerde hırsızlık veya dolandırıcılık. 500 doları aşan mal hasarı. Adaleti engelleme.',
  },
  year10: {
    label: '10 Yıl',
    short: '10 Yıl',
    detail: 'Şiddet. Can güvenliğini tehlikeye atan kundakçılık. 50.000 doları aşan dolandırıcılık veya kalpazanlık.',
  },
};

const T = {
  1: {
    title: 'Çalınan Bisiklet',
    charge: 'Basit Hırsızlık',
    summary: `El yapımı bir bisiklet pazarın önünden kayboldu. Ertesi sabah sanığın, onu iki sokak ötedeki bir rehinciye doğru sürdüğü görüldü.`,
    claim: `“Onu pazarın arkasındaki bir adamdan satın aldım. Çalıntı olduğunu bilmiyordum.”`,
    occupation: 'Bisiklet Çırağı',
    witnessRole: 'Bisiklet Dükkânı Sahibi',
    witnessStatement: `O bisikleti kendim yaptım; zilin ezik pirinç başlığı var. Toby dün onu dükkânıma kadar getirip ne kadar ödeyeceğimi sordu. Nereden aldığını sorunca kaçtı.`,
    evidenceTitle: 'Rehinci Satış Senedi',
    evidenceSubtitle: `Bell & Sons Rehinci'den ele geçirildi`,
    evidenceDetail: `Rehinciden ele geçirilen imzalı bir satış senedi. Bisikletin seri numarası çalınan bisikletin seri numarasıyla eşleşiyor; satıcının imzası “T. Hale” olarak okunuyor. Bisikletin kendisi dükkânın arka odasında bulundu.`,
    explanation: `Seri numarası, imza ve Bay Coleman’ın teşhisi, çalınan bisikletin Hale’in elinde olduğunu kanıtlıyor. Bisiklet bulundu, kimse zarar görmedi ve bu ilk suç; adil ceza para cezasıdır.`,
  },
  2: {
    title: 'Kayıp Yardım Fonu',
    charge: 'Zimmet · 4.200 $',
    summary: `Kış yardım fonunda 4.200 dolar eksik. Kasaya dokunulmamış; yalnızca defter değiştirilmiş, ardından ofisteki sobada kısmen yakılmış.`,
    claim: `“O defteri bizzat ben dengeledim. Kayıp para bir kayıt hatasıydı.”`,
    occupation: 'Yardım Fonu Saymanı',
    witnessRole: 'Yardım Fonu Asistanı',
    witnessStatement: `Şemsiyemi almak için geri döndüm ve duman kokusu aldım. Margaret sobaya sayfa sayfa kâğıt atıyordu. Ne yaptığını sorduğumda bana kendi işime bakmamı söyledi.`,
    evidenceTitle: 'Yanmış Defter Sayfası',
    evidenceSubtitle: 'Ofisteki sobada bulundu',
    evidenceDetail: `Sobada bulunan yarı yanmış bir sayfa. “Vale Danışmanlık” hesabına yapılan ve toplamı 4.200 doları bulan dört transferi kaydediyor. Hesap, para kaybolmadan on bir gün önce sanığın adına açılmış.`,
    explanation: `Transferler ve defteri yok etme girişimi kayıt hatası değil. Yardım fonundan 4.200 dolar aldı ve kanıtı yakmaya çalıştı. Yönergelere göre bu büyüklükteki dolandırıcılığın cezası bir yıldır.`,
  },
  3: {
    title: 'Tezgâhtaki Ekmek',
    charge: 'Hırsızlık · 200 $',
    summary: `Bir fırının kasasında, bir müşteriyle yaşanan tartışmanın ardından 200 dolar eksik çıkar. Fırıncı, sanığın bir somun ekmekle parayı kapıp kaçtığını söylüyor.`,
    claim: `“Ekmeğimin parasını ödedim. Bozuklukları tezgâha koyup çıktım. Hepsi bu.”`,
    occupation: 'Liman İşçisi',
    witnessRole: 'Fırın Sahibi',
    witnessStatement: `Hiç parası yoktu; ceplerini karıştırdığını gördüm. Sonra bir somun kaptı ve fırlayıp gitti. Kasaya ulaştığımda çekmece açıktı ve para yoktu.`,
    evidenceTitle: 'İyileştirilmiş Kamera Karesi',
    evidenceSubtitle: 'Fırın güvenlik kamerası · 18.12',
    evidenceDetail: `Fırın kamerasından saat damgalı bir kare. Sanığın banknotları ve bozuklukları tezgâha koyduğunu, kasa çekmecesinin ise kapalı kaldığını gösteriyor. Para eksikliği, sanık ayrıldıktan dokuz dakika sonra, 18.21’de kayda geçmiş.`,
    explanation: `Kamera, Reed’in ödeme yaptığını ve ayrıldığında çekmecenin hâlâ kapalı olduğunu kanıtlıyor. Kasa dokuz dakika sonra, başka müşteriler tezgâha yaklaştıktan sonra eksik çıkmış. Fırıncı kötü niyetli değil, sadece yanılmış. Sanık beraat eder.`,
  },
  4: {
    title: 'Şapel Duvarı',
    charge: 'Vandalizm · 1.800 $',
    summary: `Tarihî bir şapelin duvarı gece boyunca göz alıcı bir duvar resmiyle boyanmış. Restorasyon uzmanları hasarı 1.800 dolar olarak hesaplıyor; bu, basit bir temizliğin çok ötesinde.`,
    claim: `“Geçimimi duvar boyayarak kazanıyorum ama o şapele dokunmadım. Birileri imzamı taklit etmiş olmalı.”`,
    occupation: 'Duvar Ressamı',
    witnessRole: 'Şapel Bekçisi',
    witnessStatement: `Onu sabah altıda, elleri kırmızı boyayla kaplı ve ayaklarının dibinde bir sprey kutusu varken buldum. Duvardaki iz de aynı. Buna “kamusal sanat” dedi.`,
    evidenceTitle: 'Sprey Kutusu ve Yeni İmza',
    evidenceSubtitle: 'Olay yerinde bulundu',
    evidenceDetail: `Olay yerinde bulunan kırmızı bir sprey kutusu. Memesi duvardaki boyayla uyuşuyor ve kutunun üzerinde sanığın atölyesine ait envanter etiketi var. İmza, Marlow’un imzasını taşıyan on bir önceki eserle eşleşiyor.`,
    explanation: `Atölye etiketi, uyuşan meme, imza ve şafak vakti orada bulunması tesadüf değil. Hasar 500 doları aşıyor ve hiç pişmanlık göstermedi. Adil ceza bir yıldır.`,
  },
  5: {
    title: 'Depo Yangını',
    charge: 'Kundakçılık · Hayatı Tehlikeye Sokma',
    summary: `Nehir kıyısındaki bir depo saat 02.00’de temellerine kadar yanıyor. Üstteki dairelerde yaşayan dört kişi canlarını kurtarıyor ama her şeylerini kaybediyor.`,
    claim: `“Doğu rıhtımında tur atıyordum ki dumanı gördüm. Haber vermek için koştum.”`,
    occupation: 'Gece Bekçisi',
    witnessRole: 'Komşu · Üçüncü Kat',
    witnessStatement: `Uyuyamıyordum, pencerenin önündeydim. Viktor’un yükleme kapısı boyunca bir kutudan bir şey döktüğünü, sonra bir kibrit çaktığını gördüm. Yangın büyümeden kaçtı.`,
    evidenceTitle: 'Yangın Müfettişi Raporu',
    evidenceSubtitle: 'Olay yeri incelemesi · 02.40',
    evidenceDetail: `Yükleme kapısında, endüstriyel çözücüyle hızlandırılmış iki ayrı tutuşma noktası. İkinci noktada sanığın erimiş güvenlik kartı bulundu. Sanık kartı iki gün önce kaybettiğini söylüyor.`,
    explanation: `İki ayrı tutuşma noktası kaza ihtimalini ortadan kaldırıyor. Bayan Finch hızlandırıcıyı döktüğünü gördü ve güvenlik kartı yangının tam merkezindeydi. Dört kişi yataklarında neredeyse hayatını kaybediyordu. Bu kadar canı tehlikeye atan bir suça ancak on yıl cevap verir.`,
  },
  6: {
    title: 'Kayıp Kolye',
    charge: 'Büyük Hırsızlık · 12.000 $',
    summary: `Bir otel süitinden elmas bir kolye kaybolur. Konuk, duş alırken odaya giren tek kişinin hizmetçi olduğunda ısrar eder.`,
    claim: `“Odayı temizleyip çıktım. Mücevher kutusunu hiç açmadım. Bir konuktan asla hırsızlık yapmam.”`,
    occupation: 'Otel Kat Görevlisi',
    witnessRole: 'Otel Konuğu',
    witnessStatement: `Duş alırken kolyeyi makyaj masasında bıraktım. Döndüğümde yoktu. Anahtarı olan tek kişi Lila’ydı. Başka kim olabilir ki?`,
    evidenceTitle: 'Sigorta Formu ve Kart Kaydı',
    evidenceSubtitle: 'Otel kayıtları · 21.40',
    evidenceDetail: `Kolye, sözde hırsızlıktan üç gün önce sigortalanmış. Otelin kart kaydı, Bayan Cross’un hizmetçi işini bitirip çıktıktan sonra 21.40’ta kendi süitine yeniden girdiğini gösteriyor.`,
    explanation: `Konuk, hizmetçi çıktıktan sonra süite girmiş ve kolyeyi çalındığını iddia etmeden üç gün önce sigortalamış. Deliller hırsızlığa değil, sahte bir sigorta talebine işaret ediyor. Bayan Moreau beraat eder.`,
  },
  7: {
    title: 'Klinikteki İnsülin',
