input.content:
async page => {
  const errors = [];
  page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
  page.on('console', (m) => {
    if (m.type() === 'error') errors.push('console: ' + m.text());
  });

  await page.reload({ waitUntil: 'networkidle' });
  await page.evaluate(async () => {
    const mod = await import('/src/audio.js');
    const p = mod.CourtAudio.prototype;
    window.__verdictCalls = [];
    window.__correctCalls = 0;
    window.__wrongCalls = 0;
    const ov = p.verdict;
    p.verdict = function (approved) {
      window.__verdictCalls.push(approved);
      return ov.call(this, approved);
    };
    const oc = p.correct;
    p.correct = function () { window.__correctCalls++; return oc.call(this); };
    const ow = p.wrong;
    p.wrong = function () { window.__wrongCalls++; return ow.call(this); };
  });

  await page.click('#startBtn');
  await page.waitForSelector('#intro', { state: 'hidden' });

  const cases = [
    ['guilty', 'fine'],
    ['guilty', 'year1'],
    ['innocent', null],
    ['guilty', 'year1'],
    ['guilty', 'year10'],
    ['innocent', null],
    ['innocent', null],
    ['guilty', 'year10'],
    ['innocent', null],
    ['innocent', null],
  ];

  const rows = [];
  for (let i = 0; i < cases.length; i++) {
    const [verdict, sentence] = cases[i];
    await page.waitForFunction(
      (n) => document.querySelector('#caseCounter')?.textContent?.startsWith(String(n).padStart(2, '0')),
      i + 1
    );
    const title = (await page.textContent('#caseTitle')).trim();
    if (verdict === 'guilty') {
      await page.click('#guiltyBtn');
      await page.click(`[data-sentence="${sentence}"]`);
    } else {
      await page.click('#innocentBtn');
    }
    await page.click('#confirmBtn');
    await page.waitForSelector('#resultPanel:not([hidden])', { timeout: 8000 });
    const data = await page.evaluate(() => ({
      tag: document.querySelector('#resultTag').textContent.trim(),
      title: document.querySelector('#resultTitle').textContent.trim(),
      caseNo: document.querySelector('#resultCase').textContent.trim(),
      deltas: [...document.querySelectorAll('#deltaRow .delta')].map((n) => n.textContent.trim()),
      justice: document.querySelector('#justiceVal').textContent.trim(),
      reputation: document.querySelector('#reputationVal').textContent.trim(),
      verdictCalls: window.__verdictCalls.length,
      lastApproved: window.__verdictCalls[window.__verdictCalls.length - 1],
    }));
    rows.push({ n: i + 1, title, verdict, sentence, ...data });
    await page.click('#nextBtn');
    await page.waitForTimeout(150);
  }

  await page.waitForSelector('#gameover:not([hidden])', { timeout: 8000 });
  const final = await page.evaluate(() => ({
    rank: document.querySelector('#finalRank').textContent.trim(),
    blurb: document.querySelector('#finalBlurb').textContent.trim(),
    justice: document.querySelector('#finalJustice').textContent.trim(),
    reputation: document.querySelector('#finalReputation').textContent.trim(),
    fair: document.querySelector('#finalFair').textContent.trim(),
    correct: document.querySelector('#finalCorrect').textContent.trim(),
    best: document.querySelector('#finalBest').textContent.trim(),
    verdictCalls: window.__verdictCalls,
    correctCalls: window.__correctCalls,
    wrongCalls: window.__wrongCalls,
  }));

  return { rows, final, errors };
}

